/* In-app guide content for Fanfara, one array of sections per language.
   Each section: { k: key (maps to an icon in settings.html), h: heading, p: [paragraphs...] }. */
window.FAN_GUIDE = {
  it: [
    { k:"welcome", h:"Benvenuto in Fanfara", p:["Fanfara trasforma lo sblocco degli achievement di Steam in un momento di festa — e ora conserva anche la tua storia: ogni obiettivo diventa una voce nella Cronologia e una carta nella Collezione."] },
    { k:"setup", h:"Configurazione guidata", p:["Al primo avvio Fanfara apre una guida passo passo: controlla che Steam sia aperto e che i tuoi obiettivi siano visibili (e se non lo sono ti mostra come renderli pubblici), ti fa provare la notifica e scegliere lo schermo dove vederla, spiega come impostare la modalità video dei giochi, ti fa scegliere avvio con Windows, volume e aggiornamenti, e importa la tua collezione mostrandoti l’avanzamento.", "Puoi riaprirla quando vuoi da Impostazioni → App («Configurazione guidata»), da qui o dal menu dell’icona di Fanfara vicino all’orologio, per esempio se aggiungi un secondo schermo o se una notifica non si vede."], a:"Apri la configurazione guidata", href:"welcome.html" },
    { k:"home", h:"La schermata iniziale", p:["In alto c’è sempre la barra di Fanfara: Home, Collezione, Cronologia, Classifica, Impostazioni, Guida e Feedback. Da lì passi da una sezione all’altra con un clic, da qualunque schermata; la sezione in cui sei è evidenziata.", "La Home ha due parti. In alto le impostazioni rapide, che si salvano da sole: la tua fanfara (anteprima, Prova, gli stili usati di recente, volume, posizione e durata), lo stile degli album con i suoi effetti e le scelte per i giochi al 100% (Super Fanfara, avvisi e suono degli amici, ciascuno con Prova). Sotto, «Come stai andando»: ultimi sblocchi, classifica, giochi vicini al 100% e ultimi 7 giorni — clicca un riquadro per aprire la sezione. Accanto al saluto trovi la versione di Fanfara; clicca il tuo avatar per aprire il profilo Steam."] },
    { k:"bell", h:"Notifiche (la campanella)", p:["La campanella in alto a destra nella Home raccoglie le novità: gli amici che completano un gioco al 100%, i tuoi 100%, le nuove versioni di Fanfara e le novità dell’ultimo aggiornamento. Il pallino rosso dice quante non hai ancora visto.", "Clicca una notifica per andare al punto giusto (la classifica degli amici, il tuo album, l’aggiornamento…). «Segna tutte come lette» le spunta tutte; si segnano lette anche quando chiudi il pannello. Resta tutto sul tuo PC."] },
    { k:"how", h:"Come funziona la notifica", p:["Lascia Fanfara in esecuzione — resta un'icona vicino all'orologio — e gioca. Quando sblocchi un achievement compare la fanfara: più è raro, più lo sblocco è epico."] },
    { k:"style", h:"Stile della notifica", p:["Scegli l'aspetto tra decine di stili, raccolti in categorie: apri un riquadro per vederne gli stili. Passa il mouse su una card per vederla animata; premi «Con suono» per sentirla, poi clicca la card per sceglierla: si salva subito. Ogni stile ha icone diverse per rarità e un suono dedicato. Gli ultimi stili che hai usato li ritrovi anche nella Home, per cambiarli al volo."] },
    { k:"position", h:"Posizione, durata e volume", p:["Scegli in quale punto dello schermo appare la notifica (7 posizioni), per quanti secondi resta visibile e il volume del suono."] },
    { k:"history", h:"Cronologia Achievement", p:["Tutti i tuoi sblocchi su una linea del tempo, con l’ora e un pallino del colore della rarità; gli epici e i leggendari diventano riquadri grandi con l’immagine del gioco. In alto trovi il riepilogo di oggi, le statistiche e il calendario delle ultime 16 settimane; a lato il calendario del mese (con ‹ › cambi mese, cliccando un giorno vedi solo quello), la rarità e i giochi del mese. Cerca, filtra per rarità o data e usa «Carica altri giorni» per andare indietro. Resta tutto sul tuo PC."] },
    { k:"collection", h:"Collezione Achievement", p:["Ogni obiettivo sbloccato è una carta da collezione: la cornice ha il colore della rarità, le gemme ne indicano il livello e gli effetti crescono con la rarità (riflesso, pellicola olografica, scintille). In alto vedi il tuo livello da collezionista: le carte rare valgono più punti. Se dall'ultima visita hai sbloccato obiettivi nuovi ti aspetta una bustina: aprila per scoprire le carte e poi mettile nella collezione. Sotto ci sono la vetrina con le tue 5 carte più rare e i tuoi album, uno per gioco, da cercare e ordinare.", "Ogni album è un libro antico: arriva chiuso e lo apri tu con «Apri l'album», cliccando la copertina oppure con → o Invio. La prima pagina riporta carte raccolte, completamento, ore di gioco (da Steam, aggiornate con la sincronizzazione), la carta più rara e la prima carta, firmata con il tuo nome Steam («Collezione di …»). Le carte sono fissate con gli angolini in ordine di sblocco; le cornici vuote con il «?» sono gli obiettivi che ti mancano. Sfoglia cliccando la pagina o l'angolino, oppure con le frecce; Esc chiude l'album. I giochi completati al 100% hanno il sigillo d'oro sulla copertina.", "Clicca una carta (nella vetrina o in un album): si solleva, gira in aria e atterra davanti a te, con un suono che segue il volume scelto in Impostazioni. Clicca la carta (o premi Invio) per girarla: sul retro trovi quanti giocatori su 1.000 ce l'hanno, data e ora dello sblocco, la sua posizione nella tua collezione, il progresso nel gioco e quali amici che usano Fanfara ce l'hanno, con chi è arrivato prima. Esc o un clic fuori la richiude.", "Sotto la carta aperta trovi due pulsanti: «Copia immagine» copia la carta (fronte o retro) con la sua cornice, così la incolli con Ctrl+V su Discord, WhatsApp o dove vuoi; «Pubblica in bacheca» la pubblica nel canale #bacheca-trofei del server Discord di Fanfara, con il tuo nome Steam. Fanfara controlla su Steam che l'obiettivo sia davvero tuo; ogni carta si pubblica una volta sola. Dalla vetrina c'è anche «Vedi nel suo album», che apre l'album del gioco e ti porta alla pagina della carta.", "Gli album sono divisi in pagine: due file di libri per pagina. Cambi pagina con le frecce ‹ › accanto all’ordinamento, con quelle in fondo o con i tasti ← →; i pallini in basso ti dicono dove sei. Con «Medi», «Grandi» e «Molto grandi» (in alto o in Impostazioni → Album) scegli quanti libri vedere per fila: 6, 5 o 4."] },
    { k:"albumstyles", h:"Stili degli album", p:["Gli album della Collezione possono cambiare aspetto: «Classico» (quello di sempre), «Ferro e cuoio», «Grimorio reale», «Archivio olografico», «Lacca e oro» e «Ottone e ingranaggi». Ogni stile ha la sua copertina, le sue pagine, la sua cornice e il suo sfondo animato (candele, polvere, scintille, petali di ciliegio, vapore…). I giochi completati al 100% hanno un nastro «100%» sull'angolo della copertina.", "Lo scegli in Impostazioni → «Stile degli album». Lì trovi anche «Effetti degli album»: Pieni, Leggeri (meno animazioni) o Spenti, utile sui PC meno potenti."] },
    { k:"superfan", h:"Super Fanfara al 100%", p:["Quando sblocchi l’ultimo obiettivo di un gioco parte la Super Fanfara: subito dopo la notifica normale arriva un grande «100%» dorato con l’immagine del gioco, le tue ore di gioco, quale numero di 100% è per te, coriandoli e una musica orchestrale.", "Si attiva e si spegne in Impostazioni → «Super Fanfara al 100%». Il gioco viene anche segnato subito al 100% in classifica."] },
    { k:"classifica", h:"Classifica", p:["Una gara a chi completa più giochi al 100% (tutti gli obiettivi sbloccati). «I tuoi giochi» mostra i tuoi giochi completati come carte; «Mondiale» è la classifica pubblica di tutti gli utenti Fanfara, in cui entri solo se vuoi; «Amici» ti confronta con i tuoi amici Steam che usano Fanfara. Il punteggio è calcolato sul tuo PC, senza login."] },
    { k:"friendcoll", h:"Collezioni degli amici", p:["In «Classifica → Amici», accanto a ogni amico che usa Fanfara c’è il pulsante «Collezione»: cliccandolo sfogli la sua collezione (vetrina, album e carte) e la confronti con la tua. In alto vedi quante carte avete in comune, quante ti mancano e quante sono solo tue; ogni carta ha il bollino «Ce l’hai» o «Ti manca», sotto ogni album c’è anche il tuo progresso e puoi mostrare solo i giochi che avete entrambi.", "Dopo ogni sincronizzazione Fanfara manda una copia leggera della tua collezione al suo servizio online, e solo i tuoi amici di Steam possono vederla. La condivisione è accesa di base: puoi spegnerla in Impostazioni («Condividi la mia collezione con gli amici») e la copia online viene cancellata. Per vedere le collezioni degli amici la tua lista amici di Steam deve essere pubblica."] },
    { k:"friend100", h:"Amici al 100%", p:["Se un tuo amico di Steam usa Fanfara e completa un gioco al 100%, ti arriva una notifica in basso a destra — anche mentre giochi — con il gioco, i suoi giochi al 100% contro i tuoi, e due rintocchi leggeri. La trovi anche nella campanella della Home.", "In Impostazioni puoi spegnere queste notifiche («Avvisami quando un amico arriva al 100%») o solo il loro suono. Funziona per gli amici che hanno Fanfara 0.6.0 o più recente e partecipano alla classifica."] },
    { k:"sync", h:"Sincronizzazione automatica", p:["Al primo avvio Fanfara importa da sola tutti i tuoi obiettivi, con icone, date e rarità reali e senza login. Poi cattura gli sblocchi dal vivo mentre giochi.", "Quando chiudi un gioco aggiorna subito quel gioco (icone, rarità, stato 100%); ogni 12 ore fa un controllo completo, anche se resta aperta. Puoi forzarlo dal riquadro «Sincronizzato» in Home. Serve il profilo Steam con «Il mio profilo» e «Dettagli dei giochi» su Pubblico: con «Solo amici» o «Privato» Steam nasconde gli obiettivi e Fanfara non può importarli. In quel caso la Home mostra un avviso rosso con «Come risolvere», le notifiche continuano a funzionare e Fanfara ricontrolla da sola ogni 30 minuti.", "Steam è il riferimento: se azzeri degli obiettivi su Steam (per esempio con un programma apposito), alla sincronizzazione completa successiva spariscono anche da Cronologia, Collezione e classifica. Steam può impiegare fino a un’ora a mostrare il cambiamento."] },
    { k:"language", h:"Lingua", p:["Fanfara parla 5 lingue. Con «Auto» segue Windows, oppure ne scegli una dall'elenco. È tradotto tutto, anche i nomi dei ranghi di ogni stile."] },
    { k:"theme", h:"Tema chiaro e scuro", p:["Il pulsante in alto a destra cambia l'aspetto di tutta l'app tra tema chiaro e scuro."] },
    { k:"startup", h:"Avvio con Windows e aggiornamenti", p:["«Avvia all'accensione del PC» fa partire Fanfara da solo, pronto nel tray. «Controlla aggiornamenti all'avvio» ti avvisa delle nuove versioni, installabili con un clic: Fanfara controlla all'avvio, ogni ora mentre resta aperta e quando riapri la finestra. Accanto c'è «Cerca ora» per controllare subito: se c'è una versione nuova compare «Aggiorna ora».", "Quando esce una nuova versione, nella Home compare un avviso in basso a destra: premi «Aggiorna ora» e Fanfara scarica l’aggiornamento, controlla che sia autentico, si chiude, si installa da sola e si riapre in pochi secondi, mostrandoti le novità. Se stai giocando aspetta che chiudi il gioco. Con «Più tardi» l’avviso sparisce, ma lo ritrovi nella campanella."] },
    { k:"games", h:"Notifiche nei giochi", p:["L'opzione «Mostra le notifiche nei giochi a schermo intero» (consigliata, già attiva) prepara i tuoi giochi Steam perché le notifiche compaiano anche in gioco. Non devi fare nulla."] },
    { k:"exclusive", h:"Schermo intero esclusivo", p:["Se un gioco è impostato su «Schermo intero esclusivo» (o «Exclusive fullscreen»), la notifica si sente ma non si vede: in quella modalità Windows non lascia disegnare nulla sopra il gioco.", "Soluzione: nelle opzioni video del gioco scegli «Schermo intero» senza esclusivo (in alcuni giochi si chiama «Borderless» o «Finestra senza bordi»). Il gioco usa comunque la frequenza del monitor impostata in Windows, per esempio 165 Hz. Se Fanfara si accorge che un gioco era in esclusivo, te lo ricorda quando lo chiudi."] },
    { k:"screens", h:"Più schermi", p:["Con due o più schermi la notifica compare, di serie, sullo schermo dove stai giocando (quello con la finestra attiva). Se preferisci vederla sempre su uno schermo preciso, sceglilo nella Configurazione guidata al passo «Prova».", "Se senti il suono ma non vedi la notifica, apri la Configurazione guidata, prova la notifica e scegli lo schermo giusto; se succede solo dentro un gioco, controlla la modalità video (vedi «Schermo intero esclusivo»)."] },
    { k:"framegen", h:"Frame Generation (avanzato)", p:["Alcuni giochi con Frame Generation (DLSS 3, FSR 3) nascondono gli overlay esterni anche in «Schermo intero». Attiva questa opzione per vedere le notifiche anche lì: serve l'amministratore e un riavvio, una volta sola. È reversibile e senza rischi anticheat."] },
    { k:"steamtip", h:"Consiglio: disattiva la notifica di Steam", p:["Per non vedere i doppioni, disattiva quella standard di Steam: Steam → Impostazioni → Nel gioco → togli la notifica di sblocco achievement."] },
    { k:"testsave", h:"Impostazioni a schede, salvate da sole", p:["Le Impostazioni sono divise in quattro schede: Notifica (stile, posizione, durata, volume e il pulsante Prova), Album (stile e effetti degli album, grandezza dei libri nella Collezione), Amici e 100% (condivisione della collezione, Super Fanfara, avvisi e suono degli amici) e App (lingua, configurazione guidata, avvio con Windows, aggiornamenti, notifiche nei giochi e Frame Generation).", "Non c’è più il pulsante Salva: ogni modifica si salva da sola e compare un piccolo «Salvato ✓». Il pulsante Prova mostra un’anteprima della notifica con le scelte del momento."] },
    { k:"feedback", h:"Feedback", p:["Hai trovato un problema o hai un'idea? Premi «Feedback» nella barra in alto (c’è anche nel menu dell'icona vicino all'orologio): scrivi due righe e il messaggio arriva direttamente a chi sviluppa Fanfara.", "Insieme al testo vengono inviate solo la versione di Fanfara, la lingua e la versione di Windows. Per i problemi puoi allegare il registro tecnico, ripulito dai dati personali."], a:"Invia feedback", href:"feedback.html" },
    { k:"opensource", h:"Progetto open source", p:["Fanfara è gratis e open source. Codice e novità su GitHub: github.com/AmbroJack27/FanfaraOverlay. Progetto amatoriale, non affiliato né approvato dalle case produttrici."] }
  ],
  en: [
    { k:"welcome", h:"Welcome to Fanfara", p:["Fanfara turns unlocking Steam achievements into a celebration — and now it keeps your story too: every achievement becomes an entry in your History and a card in your Collection."] },
    { k:"setup", h:"Guided setup", p:["On first launch Fanfara opens a step-by-step guide: it checks that Steam is running and that your achievements are visible (and if they aren’t, shows you how to make them public), lets you test the notification and pick the screen to show it on, explains how to set the games’ display mode, lets you choose start with Windows, volume and updates, and imports your collection showing the progress.", "You can reopen it any time from Settings → App («Guided setup»), from here or from the menu of Fanfara’s icon next to the clock — for example if you add a second screen or a notification doesn’t show."], a:"Open the guided setup", href:"welcome.html" },
    { k:"home", h:"The Home screen", p:["Fanfara’s bar is always at the top: Home, Collection, History, Leaderboard, Settings, Guide and Feedback. Use it to jump from one section to another with one click, from any screen; the section you are in is highlighted.", "The Home has two parts. At the top, the quick settings, which save themselves: your fanfare (preview, Test, recently used styles, volume, position and duration), the album style with its effects and the choices for games at 100% (Super Fanfara, friends’ alerts and their sound, each with Test). Below, «How you’re doing»: latest unlocks, leaderboard, games close to 100% and the last 7 days — click a box to open its section. Fanfara’s version sits next to the greeting; click your avatar to open your Steam profile."] },
    { k:"bell", h:"Notifications (the bell)", p:["The bell at the top right of the Home collects the news: friends who complete a game 100%, your own 100%s, new Fanfara versions and what’s new in the latest update. The red dot tells you how many you haven’t seen yet.", "Click a notification to jump to the right place (the friends leaderboard, your album, the update…). «Mark all as read» ticks them all; they are also marked as read when you close the panel. Everything stays on your PC."] },
    { k:"how", h:"How the notification works", p:["Leave Fanfara running — it stays as an icon near the clock — and just play. When you unlock an achievement, the fanfare appears: the rarer it is, the more epic the unlock."] },
    { k:"style", h:"Notification style", p:["Pick the look from dozens of styles, grouped in categories: open a box to see its styles. Hover a card to see it animate; press «With sound» to hear it, then click the card to pick it: it is saved straight away. Every style has per-rarity icons and a built-in sound. The styles you used last are also on the Home, to switch on the fly."] },
    { k:"position", h:"Position, duration and volume", p:["Choose where the notification appears on screen (7 positions), how many seconds it stays visible, and the sound volume."] },
    { k:"history", h:"Achievement History", p:["All your unlocks on a timeline, with the time and a dot in the rarity colour; epic and legendary ones become big cards with the game’s artwork. At the top: today’s summary, your stats and a calendar of the last 16 weeks; on the side: the month calendar (‹ › changes month, clicking a day shows only that day), the month’s rarity and games. Search, filter by rarity or date and use “Load more days” to go back in time. It all stays on your PC."] },
    { k:"collection", h:"Achievement Collection", p:["Every unlocked achievement is a trading card: the frame takes the rarity colour, the gems show its level and the effects grow with rarity (light sweep, holographic foil, sparkles). At the top you see your collector level: rare cards are worth more points. If you unlocked new achievements since your last visit, a pack is waiting: open it to reveal the cards, then add them to the collection. Below are the showcase with your 5 rarest cards and your albums, one per game, which you can search and sort.", "Each album is an old book: it arrives closed and you open it with «Open the album», by clicking the cover or with → or Enter. The first page shows cards collected, completion, hours played (from Steam, updated when you sync), the rarest card and the first card, signed with your Steam name («Collection of …»). Cards are held by photo corners in unlock order; empty frames with a «?» are the achievements you're still missing. Turn pages by clicking the page or its corner, or with the arrow keys; Esc closes the album. Games completed 100% get a gold seal on the cover.", "Click a card (in the showcase or in an album): it lifts off, spins in the air and lands in front of you, with a sound that follows the volume set in Settings. Click the card (or press Enter) to flip it: the back shows how many players in 1,000 have it, the unlock date and time, its place in your collection, your progress in the game and which friends who use Fanfara have it — and who got it first. Esc or a click outside closes it.", "Below the opened card there are two buttons: «Copy image» copies the card (front or back) with its frame, so you can paste it with Ctrl+V on Discord, WhatsApp or anywhere; «Post to the showcase» posts it to #bacheca-trofei on the Fanfara Discord server, with your Steam name. Fanfara checks on Steam that the achievement is really yours; each card can be posted once. From the showcase there's also «See it in its album», which opens the game's album at the card's page.", "Albums are split into pages: two rows of books per page. Turn the page with the ‹ › arrows next to the sorting, with the ones at the bottom or with the ← → keys; the dots at the bottom show where you are. With «Medium», «Large» and «Very large» (at the top, or in Settings → Albums) you choose how many books per row: 6, 5 or 4."] },
    { k:"albumstyles", h:"Album styles", p:["The Collection albums can change look: «Classic» (the usual one), «Iron & leather», «Royal grimoire», «Holo archive», «Lacquer & gold» and «Brass & gears». Each style has its own cover, pages, frame and animated backdrop (candles, dust, sparks, cherry petals, steam…). Games completed 100% get a «100%» ribbon across the corner of the cover.", "Pick it in Settings → «Album style». There you also find «Album effects»: Full, Light (fewer animations) or Off, handy on less powerful PCs."] },
    { k:"superfan", h:"Super Fanfara at 100%", p:["When you unlock a game’s last achievement, the Super Fanfara plays: right after the normal notification comes a big golden «100%» with the game’s picture, your hours played, which number 100% it is for you, confetti and orchestral music.", "Turn it on or off in Settings → «Super Fanfara at 100%». The game is also marked 100% in the leaderboard right away."] },
    { k:"classifica", h:"Leaderboard", p:["A race to complete the most games 100% (every achievement unlocked). «Your games» shows your completed games as cards; «World» is the public leaderboard of all Fanfara users, which you join only if you want; «Friends» compares you with your Steam friends who use Fanfara. Your score is computed on your own PC, no login."] },
    { k:"friendcoll", h:"Friends’ collections", p:["In «Leaderboard → Friends», every friend who uses Fanfara has a «Collection» button: click it to browse their collection (showcase, albums and cards) and compare it with yours. At the top you see how many cards you share, how many you’re missing and how many are only yours; every card is marked «You have it» or «Missing», each album also shows your progress, and you can show only the games you both have.", "After each sync Fanfara sends a light copy of your collection to its online service, and only your Steam friends can see it. Sharing is on by default: turn it off in Settings («Share my collection with friends») and the online copy is deleted. To see your friends’ collections, your Steam friends list must be public."] },
    { k:"friend100", h:"Friends at 100%", p:["If one of your Steam friends uses Fanfara and completes a game 100%, you get a notification at the bottom right — even while you play — with the game, their 100% games versus yours, and two soft chimes. You also find it in the Home bell.", "In Settings you can turn these notifications off («Tell me when a friend hits 100%») or just their sound. It works for friends on Fanfara 0.6.0 or newer who take part in the leaderboard."] },
    { k:"sync", h:"Automatic sync", p:["On first launch Fanfara imports all your achievements by itself, with real icons, dates and rarity, no login. Then it captures unlocks live while you play.", "When you close a game it refreshes that game right away (icons, rarity, 100% status); every 12 hours it runs a full check, even if it stays open. You can force it from the «Synced» chip on the Home. Your Steam profile needs «My profile» and «Game details» set to Public: with «Friends only» or «Private», Steam hides your achievements and Fanfara can’t import them. In that case the Home shows a red notice with «How to fix it», notifications keep working and Fanfara checks again on its own every 30 minutes.", "Steam is the reference: if you reset achievements on Steam (for example with a dedicated tool), the next full sync removes them from the History, the Collection and the leaderboard too. Steam can take up to an hour to show the change."] },
    { k:"language", h:"Language", p:["Fanfara speaks 5 languages. «Auto» follows Windows, or pick one from the list. Everything is translated, including each style's rank names."] },
    { k:"theme", h:"Light and dark theme", p:["The button at the top right switches the whole app between light and dark theme."] },
    { k:"startup", h:"Start with Windows and updates", p:["«Start when the PC turns on» launches Fanfara on its own, ready in the tray. «Check for updates at startup» notifies you of new versions, installable in one click: Fanfara checks at startup, every hour while it stays open and when you open its window again. Next to it, «Check now» checks right away: if there is a new version, «Update now» appears.", "When a new version comes out, a notice appears at the bottom right of the Home: press «Update now» and Fanfara downloads the update, checks it’s genuine, closes, installs itself and reopens in a few seconds, showing you what’s new. If you are playing, it waits until you close the game. «Later» hides the notice, but you’ll still find it in the bell."] },
    { k:"games", h:"Notifications in games", p:["The «Show notifications over fullscreen games» option (recommended, already on) prepares your Steam games so notifications also appear in-game. You don't have to do anything."] },
    { k:"exclusive", h:"Exclusive fullscreen", p:["If a game is set to «Exclusive fullscreen», you hear the notification but don't see it: in that mode Windows lets nothing draw on top of the game.", "Fix: in the game's video options pick «Fullscreen» without exclusive (some games call it «Borderless» or «Borderless window»). The game still runs at the refresh rate set in Windows, e.g. 165 Hz. If Fanfara notices a game was in exclusive mode, it reminds you when you close it."] },
    { k:"screens", h:"Multiple screens", p:["With two or more screens, the notification shows by default on the screen where you’re playing (the one with the active window). If you’d rather always see it on a specific screen, choose it in the Guided setup, at the «Test» step.", "If you hear the sound but don’t see the notification, open the Guided setup, test the notification and pick the right screen; if it only happens inside a game, check its display mode (see «Exclusive fullscreen»)."] },
    { k:"framegen", h:"Frame Generation (advanced)", p:["Some games with Frame Generation (DLSS 3, FSR 3) hide external overlays even in «Fullscreen». Turn this on to see notifications there too: needs administrator and a one-time restart. It's reversible and anti-cheat-safe."] },
    { k:"steamtip", h:"Tip: turn off Steam's own notification", p:["To avoid duplicates, disable Steam's default one: Steam → Settings → In Game → turn off the achievement-unlock notification."] },
    { k:"testsave", h:"Settings in tabs, saved by themselves", p:["Settings are split into four tabs: Notification (style, position, duration, volume and the Test button), Albums (album style and effects, size of the books in the Collection), Friends & 100% (collection sharing, Super Fanfara, friends’ alerts and their sound) and App (language, guided setup, start with Windows, updates, notifications in games and Frame Generation).", "There is no Save button any more: every change saves itself and a small «Saved ✓» appears. The Test button shows a preview of the notification with your current choices."] },
    { k:"feedback", h:"Feedback", p:["Found a problem or have an idea? Press «Feedback» in the bar at the top (it’s also in the tray icon menu): write a couple of lines and the message goes straight to Fanfara's developer.", "Only Fanfara's version, the language and the Windows version are sent with your text. For problems you can attach the technical log, cleaned of personal data."], a:"Send feedback", href:"feedback.html" },
    { k:"opensource", h:"Open-source project", p:["Fanfara is free and open-source. Code and news on GitHub: github.com/AmbroJack27/FanfaraOverlay. Fan project, not affiliated with or endorsed by the game companies."] }
  ],
  fr: [
    { k:"welcome", h:"Bienvenue dans Fanfara", p:["Fanfara transforme le déblocage des succès Steam en fête — et garde désormais ton histoire : chaque succès devient une entrée dans l'Historique et une carte dans la Collection."] },
    { k:"setup", h:"Configuration guidée", p:["Au premier lancement, Fanfara ouvre un guide pas à pas : il vérifie que Steam est ouvert et que tes succès sont visibles (et sinon il t’explique comment les rendre publics), te fait tester la notification et choisir l’écran où l’afficher, explique comment régler le mode d’affichage des jeux, te laisse choisir le lancement avec Windows, le volume et les mises à jour, puis importe ta collection en montrant la progression.", "Tu peux le rouvrir à tout moment depuis Réglages → Appli (« Configuration guidée »), d’ici ou depuis le menu de l’icône Fanfara près de l’horloge, par exemple si tu ajoutes un deuxième écran ou si une notification ne s’affiche pas."], a:"Ouvrir la configuration guidée", href:"welcome.html" },
    { k:"home", h:"L'écran d'accueil", p:["La barre de Fanfara est toujours en haut : Accueil, Collection, Historique, Classement, Réglages, Guide et Avis. Elle te permet de passer d’une section à l’autre en un clic, depuis n’importe quel écran ; la section où tu es est mise en évidence.", "L’accueil a deux parties. En haut, les réglages rapides, qui s’enregistrent tout seuls : ta fanfare (aperçu, Essayer, styles utilisés récemment, volume, position et durée), le style des albums avec ses effets et les choix pour les jeux à 100 % (Super Fanfara, alertes des amis et leur son, chacun avec Essayer). En dessous, « Où tu en es » : derniers déblocages, classement, jeux proches de 100 % et les 7 derniers jours — clique sur une case pour ouvrir sa section. La version de Fanfara est à côté du bonjour ; clique sur ton avatar pour ouvrir ton profil Steam."] },
    { k:"bell", h:"Notifications (la cloche)", p:["La cloche en haut à droite de l’Accueil regroupe les nouvelles : les amis qui terminent un jeu à 100 %, tes propres 100 %, les nouvelles versions de Fanfara et les nouveautés de la dernière mise à jour. La pastille rouge indique combien tu n’as pas encore vues.", "Clique une notification pour aller au bon endroit (le classement des amis, ton album, la mise à jour…). « Tout marquer comme lu » les coche toutes ; elles sont aussi marquées comme lues quand tu fermes le panneau. Tout reste sur ton PC."] },
    { k:"how", h:"Comment marche la notification", p:["Laisse Fanfara tourner — il reste une icône près de l'horloge — et joue. Quand tu débloques un succès, la fanfare apparaît : plus il est rare, plus c'est épique."] },
    { k:"style", h:"Style de la notification", p:["Choisis l'apparence parmi des dizaines de styles, regroupés en catégories : ouvre une case pour voir ses styles. Survole une carte pour la voir animée ; appuie sur «Avec le son» pour l'entendre, puis clique sur la carte pour la choisir : elle est enregistrée tout de suite. Chaque style a des icônes par rareté et un son dédié. Tes derniers styles utilisés sont aussi sur l’accueil, pour changer en un clic."] },
    { k:"position", h:"Position, durée et volume", p:["Choisis où la notification apparaît (7 positions), combien de secondes elle reste visible et le volume du son."] },
    { k:"history", h:"Historique des succès", p:["Tous tes déblocages sur une ligne du temps, avec l’heure et un point de la couleur de la rareté ; les épiques et légendaires deviennent de grandes cartes avec l’image du jeu. En haut : le résumé du jour, tes statistiques et un calendrier des 16 dernières semaines ; sur le côté : le calendrier du mois (‹ › change de mois, un clic sur un jour n’affiche que ce jour), la rareté et les jeux du mois. Cherche, filtre par rareté ou date et utilise « Afficher plus de jours » pour remonter le temps. Tout reste sur ton PC."] },
    { k:"collection", h:"Collection de succès", p:["Chaque succès débloqué est une carte à collectionner : le cadre prend la couleur de la rareté, les gemmes indiquent son niveau et les effets grandissent avec la rareté (reflet, film holographique, étincelles). En haut, ton niveau de collectionneur : les cartes rares valent plus de points. Si tu as débloqué de nouveaux succès depuis ta dernière visite, un paquet t'attend : ouvre-le pour découvrir les cartes, puis range-les dans la collection. Plus bas, la vitrine avec tes 5 cartes les plus rares et tes albums, un par jeu, à chercher et trier.", "Chaque album est un livre ancien : il arrive fermé et c'est toi qui l'ouvres avec « Ouvrir l'album », en cliquant sur la couverture ou avec → ou Entrée. La première page indique les cartes collectées, la progression, les heures de jeu (depuis Steam, mises à jour à la synchronisation), la carte la plus rare et la première carte, signée de ton nom Steam (« Collection de … »). Les cartes sont tenues par des coins photo dans l'ordre de déblocage ; les cadres vides avec un « ? » sont les succès qui te manquent. Tourne les pages en cliquant sur la page ou son coin, ou avec les flèches ; Échap ferme l'album. Les jeux terminés à 100 % ont un sceau doré sur la couverture.", "Clique sur une carte (dans la vitrine ou dans un album) : elle se soulève, tourne en l'air et atterrit devant toi, avec un son qui suit le volume choisi dans Réglages. Clique sur la carte (ou appuie sur Entrée) pour la retourner : au dos, combien de joueurs sur 1 000 l'ont, la date et l'heure, sa place dans ta collection, ta progression dans le jeu et quels amis utilisant Fanfara l'ont — et qui l'a eu en premier. Échap ou un clic à côté la referme.", "Sous la carte ouverte, deux boutons : « Copier l'image » copie la carte (recto ou verso) avec son cadre, à coller avec Ctrl+V sur Discord, WhatsApp ou ailleurs ; « Publier dans la vitrine » la publie dans #bacheca-trofei sur le serveur Discord de Fanfara, avec ton nom Steam. Fanfara vérifie sur Steam que le succès est bien à toi ; chaque carte se publie une seule fois. Depuis la vitrine, « Voir dans son album » ouvre l'album du jeu à la page de la carte.", "Les albums sont répartis en pages : deux rangées de livres par page. Tourne la page avec les flèches ‹ › à côté du tri, avec celles du bas ou avec les touches ← → ; les points en bas montrent où tu es. Avec « Moyens », « Grands » et « Très grands » (en haut ou dans Réglages → Albums) tu choisis combien de livres par rangée : 6, 5 ou 4."] },
    { k:"albumstyles", h:"Styles d’album", p:["Les albums de la Collection peuvent changer d’apparence : « Classique » (celui de toujours), « Fer et cuir », « Grimoire royal », « Archive holographique », « Laque et or » et « Laiton et engrenages ». Chaque style a sa couverture, ses pages, son cadre et son fond animé (bougies, poussière, étincelles, pétales de cerisier, vapeur…). Les jeux terminés à 100 % ont un ruban « 100 % » sur le coin de la couverture.", "Choisis-le dans Réglages → « Style des albums ». Tu y trouves aussi « Effets des albums » : Complets, Légers (moins d’animations) ou Désactivés, utile sur les PC moins puissants."] },
    { k:"superfan", h:"Super Fanfara à 100 %", p:["Quand tu débloques le dernier succès d’un jeu, la Super Fanfara se lance : juste après la notification normale arrive un grand « 100 % » doré avec l’image du jeu, tes heures de jeu, le numéro de ce 100 % pour toi, des confettis et une musique orchestrale.", "Active-la ou désactive-la dans Réglages → « Super Fanfara à 100 % ». Le jeu est aussi compté à 100 % dans le classement tout de suite."] },
    { k:"classifica", h:"Classement", p:["Une course à qui termine le plus de jeux à 100 % (tous les succès débloqués). « Tes jeux » montre tes jeux terminés sous forme de cartes ; « Monde » est le classement public de tous les utilisateurs de Fanfara, que tu rejoins seulement si tu le veux ; « Amis » te compare à tes amis Steam qui utilisent Fanfara. Le score est calculé sur ton PC, sans connexion."] },
    { k:"friendcoll", h:"Collections des amis", p:["Dans « Classement → Amis », chaque ami qui utilise Fanfara a un bouton « Collection » : clique dessus pour parcourir sa collection (vitrine, albums et cartes) et la comparer à la tienne. En haut tu vois combien de cartes vous avez en commun, combien te manquent et combien sont rien qu’à toi ; chaque carte indique « Tu l’as » ou « Te manque », chaque album montre aussi ta progression, et tu peux n’afficher que les jeux que vous avez tous les deux.", "Après chaque synchronisation, Fanfara envoie une copie légère de ta collection à son service en ligne, et seuls tes amis Steam peuvent la voir. Le partage est activé par défaut : désactive-le dans Réglages (« Partager ma collection avec mes amis ») et la copie en ligne est supprimée. Pour voir les collections de tes amis, ta liste d’amis Steam doit être publique."] },
    { k:"friend100", h:"Amis à 100 %", p:["Si un de tes amis Steam utilise Fanfara et termine un jeu à 100 %, tu reçois une notification en bas à droite — même en jouant — avec le jeu, ses jeux à 100 % contre les tiens et deux carillons légers. Tu la retrouves aussi dans la cloche de l’Accueil.", "Dans Réglages tu peux désactiver ces notifications (« Me prévenir quand un ami atteint 100 % ») ou seulement leur son. Cela marche pour les amis qui ont Fanfara 0.6.0 ou plus récent et participent au classement."] },
    { k:"sync", h:"Synchronisation automatique", p:["Au premier lancement, Fanfara importe tous tes succès toute seule, avec icônes, dates et rareté réelles, sans connexion. Ensuite elle capte les succès en direct pendant que tu joues.", "Quand tu fermes un jeu, elle met aussitôt ce jeu à jour (icônes, rareté, 100 %) ; toutes les 12 heures elle fait une vérification complète, même si elle reste ouverte. Tu peux la lancer depuis la pastille « Synchronisé » de l'accueil. Ton profil Steam doit avoir « Mon profil » et « Détails des jeux » sur Public : en « Amis uniquement » ou « Privé », Steam masque tes succès et Fanfara ne peut pas les importer. Dans ce cas, l’accueil affiche un avis rouge avec « Comment régler », les notifications continuent de fonctionner et Fanfara revérifie toute seule toutes les 30 minutes.", "Steam fait foi : si tu réinitialises des succès sur Steam (par exemple avec un outil dédié), la synchronisation complète suivante les retire aussi de l’Historique, de la Collection et du classement. Steam peut mettre jusqu’à une heure à afficher le changement."] },
    { k:"language", h:"Langue", p:["Fanfara parle 5 langues. « Auto » suit Windows, ou choisis-en une. Tout est traduit, y compris les noms des rangs de chaque style."] },
    { k:"theme", h:"Thème clair et sombre", p:["Le bouton en haut à droite bascule toute l'application entre thème clair et sombre."] },
    { k:"startup", h:"Démarrage avec Windows et mises à jour", p:["« Lancer au démarrage du PC » lance Fanfara tout seul, prêt dans la zone de notification. « Vérifier les mises à jour » t'avertit des nouvelles versions, installables en un clic : Fanfara vérifie au démarrage, toutes les heures tant qu’il reste ouvert et quand tu rouvres sa fenêtre. À côté, « Vérifier » contrôle tout de suite : s’il y a une nouvelle version, « Mettre à jour » apparaît.", "Quand une nouvelle version sort, un avis apparaît en bas à droite de l’Accueil : appuie sur « Mettre à jour » et Fanfara télécharge la mise à jour, vérifie qu’elle est authentique, se ferme, s’installe toute seule et se rouvre en quelques secondes en te montrant les nouveautés. Si tu joues, elle attend que tu fermes le jeu. « Plus tard » cache l’avis, mais tu le retrouves dans la cloche."] },
    { k:"games", h:"Notifications dans les jeux", p:["L'option « Afficher les notifications dans les jeux en plein écran » (recommandée, déjà activée) prépare tes jeux Steam. Tu n'as rien à faire."] },
    { k:"exclusive", h:"Plein écran exclusif", p:["Si un jeu est réglé sur « Plein écran exclusif », tu entends la notification mais tu ne la vois pas : dans ce mode, Windows ne laisse rien s'afficher par-dessus le jeu.", "Solution : dans les options vidéo du jeu, choisis « Plein écran » sans exclusif (parfois appelé « Sans bordure » ou « Fenêtré sans bordure »). Le jeu utilise quand même la fréquence réglée dans Windows, par exemple 165 Hz. Si Fanfara remarque qu'un jeu était en exclusif, elle te le rappelle quand tu le fermes."] },
    { k:"screens", h:"Plusieurs écrans", p:["Avec deux écrans ou plus, la notification s’affiche par défaut sur l’écran où tu joues (celui de la fenêtre active). Si tu préfères la voir toujours sur un écran précis, choisis-le dans la Configuration guidée, à l’étape « Test ».", "Si tu entends le son sans voir la notification, ouvre la Configuration guidée, teste la notification et choisis le bon écran ; si cela n’arrive qu’en jeu, vérifie son mode d’affichage (voir « Plein écran exclusif »)."] },
    { k:"framegen", h:"Frame Generation (avancé)", p:["Certains jeux avec Frame Generation (DLSS 3, FSR 3) masquent les overlays externes même en « Plein écran ». Active cette option pour voir les notifications là aussi : droits administrateur et un redémarrage, une seule fois. Réversible et sans risque anticheat."] },
    { k:"steamtip", h:"Astuce : désactive la notification de Steam", p:["Pour éviter les doublons, désactive celle de Steam : Steam → Paramètres → En jeu → désactive la notification de déblocage de succès."] },
    { k:"testsave", h:"Réglages en onglets, enregistrés tout seuls", p:["Les Réglages sont répartis en quatre onglets : Notification (style, position, durée, volume et le bouton Essayer), Albums (style et effets des albums, taille des livres dans la Collection), Amis et 100 % (partage de la collection, Super Fanfara, alertes des amis et leur son) et Appli (langue, configuration guidée, lancement avec Windows, mises à jour, notifications dans les jeux et Frame Generation).", "Il n’y a plus de bouton Enregistrer : chaque modification s’enregistre toute seule et un petit « Enregistré ✓ » apparaît. Le bouton Essayer montre un aperçu de la notification avec tes choix du moment."] },
    { k:"feedback", h:"Avis", p:["Un problème ou une idée ? Appuie sur « Avis » dans la barre du haut (aussi dans le menu de l'icône près de l'horloge) : écris deux lignes et le message arrive directement au développeur de Fanfara.", "Seules la version de Fanfara, la langue et la version de Windows sont envoyées avec ton texte. Pour un problème, tu peux joindre le journal technique, nettoyé des données personnelles."], a:"Envoyer un avis", href:"feedback.html" },
    { k:"opensource", h:"Projet open source", p:["Fanfara est gratuit et open source. Code et nouveautés sur GitHub : github.com/AmbroJack27/FanfaraOverlay. Projet amateur, non affilié aux éditeurs ni approuvé par eux."] }
  ],
  de: [
    { k:"welcome", h:"Willkommen bei Fanfara", p:["Fanfara macht das Freischalten von Steam-Erfolgen zum Fest — und bewahrt jetzt auch deine Geschichte: jeder Erfolg wird ein Eintrag im Verlauf und eine Karte in der Sammlung."] },
    { k:"setup", h:"Geführte Einrichtung", p:["Beim ersten Start öffnet Fanfara eine Schritt-für-Schritt-Anleitung: Sie prüft, ob Steam läuft und deine Erfolge sichtbar sind (und zeigt dir sonst, wie du sie öffentlich machst), lässt dich die Benachrichtigung testen und den Bildschirm dafür wählen, erklärt den Anzeigemodus der Spiele, lässt dich Autostart, Lautstärke und Updates einstellen und importiert deine Sammlung mit Fortschrittsanzeige.", "Du kannst sie jederzeit über Einstellungen → App („Geführte Einrichtung“), hier oder über das Menü des Fanfara-Symbols neben der Uhr wieder öffnen – zum Beispiel, wenn du einen zweiten Bildschirm anschließt oder eine Benachrichtigung nicht erscheint."], a:"Geführte Einrichtung öffnen", href:"welcome.html" },
    { k:"home", h:"Der Startbildschirm", p:["Oben ist immer die Leiste von Fanfara: Start, Sammlung, Verlauf, Rangliste, Einstellungen, Anleitung und Feedback. Damit wechselst du von jedem Bildschirm aus mit einem Klick den Bereich; der Bereich, in dem du bist, ist hervorgehoben.", "Die Startseite hat zwei Teile. Oben die Schnelleinstellungen, die sich selbst speichern: deine Fanfare (Vorschau, Testen, zuletzt genutzte Stile, Lautstärke, Position und Dauer), der Album-Stil mit seinen Effekten und die Optionen für Spiele mit 100 % (Super-Fanfara, Freunde-Hinweise und ihr Ton, jeweils mit Testen). Darunter „So läuft es“: letzte Freischaltungen, Rangliste, Spiele kurz vor 100 % und die letzten 7 Tage – klicke auf ein Feld, um den Bereich zu öffnen. Die Fanfara-Version steht neben der Begrüßung; ein Klick auf deinen Avatar öffnet dein Steam-Profil."] },
    { k:"bell", h:"Benachrichtigungen (die Glocke)", p:["Die Glocke oben rechts in der Startseite sammelt die Neuigkeiten: Freunde, die ein Spiel zu 100 % abschließen, deine eigenen 100 %, neue Fanfara-Versionen und die Neuerungen des letzten Updates. Der rote Punkt zeigt, wie viele du noch nicht gesehen hast.", "Klicke eine Benachrichtigung an, um an die richtige Stelle zu springen (Freunde-Rangliste, dein Album, das Update…). «Alle als gelesen markieren» hakt alle ab; sie werden auch beim Schließen des Fensters als gelesen markiert. Alles bleibt auf deinem PC."] },
    { k:"how", h:"So funktioniert die Benachrichtigung", p:["Lass Fanfara laufen — es bleibt ein Symbol neben der Uhr — und spiel. Beim Freischalten erscheint die Fanfare: je seltener, desto epischer."] },
    { k:"style", h:"Benachrichtigungsstil", p:["Wähle das Aussehen aus Dutzenden Stilen, in Kategorien gruppiert: Öffne eine Kachel, um ihre Stile zu sehen. Fahre mit der Maus über eine Karte, um sie animiert zu sehen; drücke «Mit Ton», um sie zu hören, und klicke dann auf die Karte: Sie wird sofort gespeichert. Jeder Stil hat Symbole je Seltenheit und einen eigenen Klang. Deine zuletzt genutzten Stile findest du auch auf der Startseite, zum schnellen Wechseln."] },
    { k:"position", h:"Position, Dauer und Lautstärke", p:["Lege fest, wo die Benachrichtigung erscheint (7 Positionen), wie lange sie sichtbar bleibt und die Lautstärke."] },
    { k:"history", h:"Erfolgs-Verlauf", p:["Alle deine Freischaltungen auf einer Zeitleiste, mit Uhrzeit und einem Punkt in der Farbe der Seltenheit; epische und legendäre werden zu großen Karten mit dem Bild des Spiels. Oben: die Zusammenfassung von heute, deine Statistiken und ein Kalender der letzten 16 Wochen; seitlich: der Monatskalender (‹ › wechselt den Monat, ein Klick auf einen Tag zeigt nur diesen), Seltenheit und Spiele des Monats. Suche, filtere nach Seltenheit oder Datum und nutze „Weitere Tage laden“, um zurückzugehen. Alles bleibt auf deinem PC."] },
    { k:"collection", h:"Erfolgssammlung", p:["Jeder freigeschaltete Erfolg ist eine Sammelkarte: Der Rahmen hat die Farbe der Seltenheit, die Edelsteine zeigen die Stufe und die Effekte wachsen mit der Seltenheit (Lichtreflex, Hologrammfolie, Funken). Oben siehst du deine Sammler-Stufe: Seltene Karten bringen mehr Punkte. Hast du seit deinem letzten Besuch neue Erfolge freigeschaltet, wartet ein Päckchen: Öffne es, um die Karten aufzudecken, und lege sie dann in die Sammlung. Darunter findest du die Vitrine mit deinen 5 seltensten Karten und deine Alben, eins pro Spiel, die du suchen und sortieren kannst.", "Jedes Album ist ein altes Buch: Es kommt geschlossen an und du öffnest es mit «Album öffnen», mit einem Klick auf den Einband oder mit → bzw. Enter. Die erste Seite zeigt gesammelte Karten, Fortschritt, Spielzeit (von Steam, bei der Synchronisierung aktualisiert), die seltenste und die erste Karte – unterschrieben mit deinem Steam-Namen («Sammlung von …»). Die Karten stecken in Fotoecken, in der Reihenfolge der Freischaltung; leere Rahmen mit «?» sind die Erfolge, die dir noch fehlen. Blättere mit einem Klick auf die Seite oder ihre Ecke oder mit den Pfeiltasten; Esc schließt das Album. Zu 100 % abgeschlossene Spiele tragen ein goldenes Siegel auf dem Einband.", "Klicke auf eine Karte (in der Vitrine oder in einem Album): Sie hebt ab, dreht sich in der Luft und landet vor dir – mit einem Klang, der der Lautstärke aus Einstellungen folgt. Klicke auf die Karte (oder drücke Enter), um sie umzudrehen: Auf der Rückseite siehst du, wie viele von 1.000 Spielern ihn haben, Datum und Uhrzeit, ihren Platz in deiner Sammlung, deinen Fortschritt im Spiel und welche Freunde mit Fanfara ihn haben – und wer zuerst. Esc oder ein Klick daneben schließt sie.", "Unter der geöffneten Karte gibt es zwei Tasten: «Bild kopieren» kopiert die Karte (Vorder- oder Rückseite) mit Rahmen, zum Einfügen mit Strg+V in Discord, WhatsApp oder überall; «In der Vitrine posten» postet sie in #bacheca-trofei auf dem Fanfara-Discord, mit deinem Steam-Namen. Fanfara prüft auf Steam, dass der Erfolg wirklich dir gehört; jede Karte kann einmal gepostet werden. In der Vitrine gibt es außerdem «Im Album zeigen»: Es öffnet das Album des Spiels auf der Seite der Karte.", "Die Alben sind in Seiten aufgeteilt: zwei Reihen Bücher pro Seite. Blättere mit den Pfeilen ‹ › neben der Sortierung, mit denen unten oder mit den Tasten ← →; die Punkte unten zeigen, wo du bist. Mit „Mittel“, „Groß“ und „Sehr groß“ (oben oder unter Einstellungen → Alben) wählst du, wie viele Bücher pro Reihe: 6, 5 oder 4."] },
    { k:"albumstyles", h:"Album-Stile", p:["Die Alben der Sammlung können ihr Aussehen ändern: «Klassisch» (das bekannte), «Eisen & Leder», «Königliches Grimoire», «Holo-Archiv», «Lack & Gold» und «Messing & Zahnräder». Jeder Stil hat eigenen Einband, eigene Seiten, eigenen Rahmen und einen animierten Hintergrund (Kerzen, Staub, Funken, Kirschblüten, Dampf…). Zu 100 % abgeschlossene Spiele tragen ein «100 %»-Band über der Ecke des Einbands.", "Du wählst ihn unter Einstellungen → «Album-Stil». Dort findest du auch «Album-Effekte»: Voll, Leicht (weniger Animationen) oder Aus – praktisch auf schwächeren PCs."] },
    { k:"superfan", h:"Super-Fanfara bei 100 %", p:["Wenn du den letzten Erfolg eines Spiels freischaltest, startet die Super-Fanfara: direkt nach der normalen Benachrichtigung kommt ein großes goldenes «100 %» mit dem Bild des Spiels, deinen Spielstunden, der wievielte 100 %-Abschluss es für dich ist, Konfetti und Orchestermusik.", "Ein- und ausschalten unter Einstellungen → «Super-Fanfara bei 100 %». Das Spiel wird außerdem sofort in der Rangliste als 100 % gezählt."] },
    { k:"classifica", h:"Bestenliste", p:["Ein Wettlauf, wer die meisten Spiele zu 100 % abschließt (alle Erfolge freigeschaltet). «Deine Spiele» zeigt deine abgeschlossenen Spiele als Karten; «Welt» ist die öffentliche Bestenliste aller Fanfara-Nutzer, der du nur beitrittst, wenn du willst; «Freunde» vergleicht dich mit deinen Steam-Freunden, die Fanfara nutzen. Der Punktestand wird auf deinem PC berechnet, ohne Login."] },
    { k:"friendcoll", h:"Sammlungen von Freunden", p:["Unter „Bestenliste → Freunde“ hat jeder Freund, der Fanfara nutzt, eine Schaltfläche „Sammlung“: Klicke darauf, um seine Sammlung (Vitrine, Alben und Karten) anzusehen und mit deiner zu vergleichen. Oben siehst du, wie viele Karten ihr gemeinsam habt, wie viele dir fehlen und wie viele nur dir gehören; jede Karte zeigt „Hast du“ oder „Fehlt dir“, jedes Album zeigt auch deinen Fortschritt, und du kannst nur die Spiele anzeigen, die ihr beide habt.", "Nach jeder Synchronisierung sendet Fanfara eine leichte Kopie deiner Sammlung an seinen Online-Dienst, und nur deine Steam-Freunde können sie sehen. Das Teilen ist standardmäßig an: Schalte es unter Einstellungen („Meine Sammlung mit Freunden teilen“) aus, dann wird die Online-Kopie gelöscht. Um die Sammlungen deiner Freunde zu sehen, muss deine Steam-Freundesliste öffentlich sein."] },
    { k:"friend100", h:"Freunde bei 100 %", p:["Wenn ein Steam-Freund Fanfara nutzt und ein Spiel zu 100 % abschließt, bekommst du unten rechts eine Benachrichtigung – auch während du spielst – mit dem Spiel, seinen 100 %-Spielen gegen deine und zwei leisen Glockenschlägen. Du findest sie auch in der Glocke der Startseite.", "Unter Einstellungen kannst du diese Benachrichtigungen ausschalten («Benachrichtigen, wenn ein Freund 100 % erreicht») oder nur ihren Ton. Es funktioniert für Freunde mit Fanfara 0.6.0 oder neuer, die an der Rangliste teilnehmen."] },
    { k:"sync", h:"Automatische Synchronisierung", p:["Beim ersten Start importiert Fanfara alle deine Erfolge selbst, mit echten Symbolen, Daten und Seltenheit, ohne Anmeldung. Danach erfasst es Erfolge live beim Spielen.", "Wenn du ein Spiel schließt, aktualisiert es dieses Spiel sofort (Symbole, Seltenheit, 100-%-Status); alle 12 Stunden prüft es alles, auch wenn es geöffnet bleibt. Du kannst es über den Chip «Synchronisiert» auf der Startseite anstoßen. Bei deinem Steam-Profil müssen «Mein Profil» und «Spieldetails» auf Öffentlich stehen: Bei «Nur Freunde» oder «Privat» verbirgt Steam deine Erfolge und Fanfara kann sie nicht importieren. Dann zeigt die Startseite einen roten Hinweis mit «So behebst du es», Benachrichtigungen funktionieren weiter und Fanfara prüft alle 30 Minuten selbst erneut.", "Steam ist maßgeblich: Setzt du Erfolge auf Steam zurück (zum Beispiel mit einem eigenen Programm), entfernt die nächste vollständige Synchronisierung sie auch aus Verlauf, Sammlung und Rangliste. Steam kann bis zu einer Stunde brauchen, um die Änderung zu zeigen."] },
    { k:"language", h:"Sprache", p:["Fanfara spricht 5 Sprachen. «Auto» folgt Windows, oder wähle eine. Alles ist übersetzt, auch die Rang-Namen jedes Stils."] },
    { k:"theme", h:"Helles und dunkles Design", p:["Die Schaltfläche oben rechts schaltet die ganze App zwischen hellem und dunklem Design um."] },
    { k:"startup", h:"Mit Windows starten und Updates", p:["«Mit dem PC starten» startet Fanfara von selbst, bereit im Infobereich. «Beim Start nach Updates suchen» meldet neue Versionen, mit einem Klick installierbar: Fanfara prüft beim Start, stündlich solange es geöffnet ist und wenn du sein Fenster wieder öffnest. Daneben prüft «Jetzt prüfen» sofort: Gibt es eine neue Version, erscheint «Jetzt aktualisieren».", "Wenn eine neue Version erscheint, zeigt die Startseite unten rechts einen Hinweis: Drücke «Jetzt aktualisieren» und Fanfara lädt das Update, prüft seine Echtheit, schließt sich, installiert sich selbst und öffnet sich nach wenigen Sekunden wieder – mit den Neuigkeiten. Während du spielst, wartet es, bis du das Spiel schließt. «Später» blendet den Hinweis aus, in der Glocke findest du ihn weiterhin."] },
    { k:"games", h:"Benachrichtigungen in Spielen", p:["Die Option «Benachrichtigungen über Vollbildspielen anzeigen» (empfohlen, bereits an) bereitet deine Steam-Spiele vor. Du musst nichts tun."] },
    { k:"exclusive", h:"Exklusives Vollbild", p:["Ist ein Spiel auf «Exklusives Vollbild» gestellt, hörst du die Benachrichtigung, siehst sie aber nicht: In diesem Modus lässt Windows nichts über dem Spiel zeichnen.", "Lösung: Wähle in den Grafikoptionen des Spiels «Vollbild» ohne exklusiv (manchmal «Randlos» oder «Randloses Fenster»). Das Spiel läuft trotzdem mit der in Windows eingestellten Bildwiederholrate, z. B. 165 Hz. Bemerkt Fanfara, dass ein Spiel exklusiv lief, erinnert es dich beim Schließen daran."] },
    { k:"screens", h:"Mehrere Bildschirme", p:["Mit zwei oder mehr Bildschirmen erscheint die Benachrichtigung standardmäßig auf dem Bildschirm, auf dem du spielst (dem mit dem aktiven Fenster). Willst du sie immer auf einem bestimmten Bildschirm sehen, wähle ihn in der Geführten Einrichtung im Schritt «Test».", "Hörst du den Klang, siehst aber keine Benachrichtigung, öffne die Geführte Einrichtung, teste die Benachrichtigung und wähle den richtigen Bildschirm; passiert es nur im Spiel, prüfe dessen Anzeigemodus (siehe «Exklusives Vollbild»)."] },
    { k:"framegen", h:"Frame Generation (erweitert)", p:["Manche Spiele mit Frame Generation (DLSS 3, FSR 3) verbergen externe Overlays sogar im «Vollbild». Schalte dies ein, um die Benachrichtigungen auch dort zu sehen: Administratorrechte und ein einmaliger Neustart. Reversibel und Anti-Cheat-sicher."] },
    { k:"steamtip", h:"Tipp: Steams Benachrichtigung ausschalten", p:["Um Dopplungen zu vermeiden, deaktiviere die von Steam: Steam → Einstellungen → Im Spiel → Erfolgs-Benachrichtigung ausschalten."] },
    { k:"testsave", h:"Einstellungen in Reitern, automatisch gespeichert", p:["Die Einstellungen sind in vier Reiter geteilt: Benachrichtigung (Stil, Position, Dauer, Lautstärke und die Schaltfläche Testen), Alben (Stil und Effekte der Alben, Größe der Bücher in der Sammlung), Freunde & 100 % (Sammlung teilen, Super-Fanfara, Freunde-Hinweise und ihr Ton) und App (Sprache, geführte Einrichtung, Autostart, Updates, Benachrichtigungen in Spielen und Frame Generation).", "Es gibt keine Speichern-Schaltfläche mehr: Jede Änderung speichert sich selbst, und ein kleines „Gespeichert ✓“ erscheint. Testen zeigt eine Vorschau der Benachrichtigung mit deiner aktuellen Auswahl."] },
    { k:"feedback", h:"Feedback", p:["Ein Problem gefunden oder eine Idee? Drücke «Feedback» in der Leiste oben (auch im Menü des Symbols neben der Uhr): Schreib ein paar Zeilen und die Nachricht geht direkt an den Entwickler von Fanfara.", "Mit deinem Text werden nur die Fanfara-Version, die Sprache und die Windows-Version gesendet. Bei Problemen kannst du das technische Protokoll anhängen, bereinigt von persönlichen Daten."], a:"Feedback senden", href:"feedback.html" },
    { k:"opensource", h:"Open-Source-Projekt", p:["Fanfara ist kostenlos und quelloffen. Code und News auf GitHub: github.com/AmbroJack27/FanfaraOverlay. Fan-Projekt, weder mit den Spieleherstellern verbunden noch von ihnen unterstützt."] }
  ],
  es: [
    { k:"welcome", h:"Bienvenido a Fanfara", p:["Fanfara convierte el desbloqueo de logros de Steam en una fiesta — y ahora también guarda tu historia: cada logro se vuelve una entrada en el Historial y una carta en la Colección."] },
    { k:"setup", h:"Configuración guiada", p:["En el primer inicio, Fanfara abre una guía paso a paso: comprueba que Steam esté abierto y que tus logros sean visibles (y si no lo son, te enseña a hacerlos públicos), te deja probar la notificación y elegir la pantalla donde verla, explica cómo configurar el modo de pantalla de los juegos, te deja elegir inicio con Windows, volumen y actualizaciones, e importa tu colección mostrando el progreso.", "Puedes volver a abrirla cuando quieras desde Ajustes → App («Configuración guiada»), desde aquí o desde el menú del icono de Fanfara junto al reloj, por ejemplo si añades una segunda pantalla o si una notificación no se ve."], a:"Abrir la configuración guiada", href:"welcome.html" },
    { k:"home", h:"La pantalla de inicio", p:["Arriba está siempre la barra de Fanfara: Inicio, Colección, Historial, Clasificación, Ajustes, Guía y Opinión. Con ella pasas de una sección a otra con un clic, desde cualquier pantalla; la sección en la que estás aparece resaltada.", "El inicio tiene dos partes. Arriba, los ajustes rápidos, que se guardan solos: tu fanfarria (vista previa, Probar, estilos usados recientemente, volumen, posición y duración), el estilo de los álbumes con sus efectos y las opciones para los juegos al 100 % (Super Fanfara, avisos de amigos y su sonido, cada uno con Probar). Debajo, «Cómo vas»: últimos desbloqueos, clasificación, juegos casi al 100 % y los últimos 7 días — haz clic en un recuadro para abrir su sección. La versión de Fanfara está junto al saludo; haz clic en tu avatar para abrir tu perfil de Steam."] },
    { k:"bell", h:"Notificaciones (la campana)", p:["La campana arriba a la derecha del Inicio reúne las novedades: amigos que completan un juego al 100 %, tus propios 100 %, nuevas versiones de Fanfara y las novedades de la última actualización. El punto rojo indica cuántas no has visto todavía.", "Haz clic en una notificación para ir al sitio correcto (la clasificación de amigos, tu álbum, la actualización…). «Marcar todas como leídas» las marca todas; también se marcan como leídas al cerrar el panel. Todo se queda en tu PC."] },
    { k:"how", h:"Cómo funciona la notificación", p:["Deja Fanfara en ejecución — queda como un icono junto al reloj — y juega. Al desbloquear un logro aparece la fanfarria: cuanto más raro, más épico."] },
    { k:"style", h:"Estilo de la notificación", p:["Elige el aspecto entre decenas de estilos, agrupados en categorías: abre un recuadro para ver sus estilos. Pasa el ratón sobre una tarjeta para verla animada; pulsa «Con sonido» para oírla y luego haz clic en la tarjeta para elegirla: se guarda al instante. Cada estilo tiene iconos por rareza y un sonido propios. Los últimos estilos que usaste también están en el inicio, para cambiar al vuelo."] },
    { k:"position", h:"Posición, duración y volumen", p:["Elige en qué punto de la pantalla aparece la notificación (7 posiciones), cuántos segundos permanece y el volumen del sonido."] },
    { k:"history", h:"Historial de logros", p:["Todos tus desbloqueos en una línea del tiempo, con la hora y un punto del color de la rareza; los épicos y legendarios se convierten en tarjetas grandes con la imagen del juego. Arriba: el resumen de hoy, tus estadísticas y un calendario de las últimas 16 semanas; al lado: el calendario del mes (‹ › cambia de mes, al pulsar un día solo ves ese día), la rareza y los juegos del mes. Busca, filtra por rareza o fecha y usa «Cargar más días» para ir atrás. Todo queda en tu PC."] },
    { k:"collection", h:"Colección de logros", p:["Cada logro desbloqueado es una carta coleccionable: el marco toma el color de la rareza, las gemas indican su nivel y los efectos crecen con la rareza (destello, lámina holográfica, chispas). Arriba ves tu nivel de coleccionista: las cartas raras valen más puntos. Si desde tu última visita desbloqueaste logros nuevos, te espera un sobre: ábrelo para descubrir las cartas y luego guárdalas en la colección. Debajo están la vitrina con tus 5 cartas más raras y tus álbumes, uno por juego, que puedes buscar y ordenar.", "Cada álbum es un libro antiguo: llega cerrado y lo abres tú con «Abrir el álbum», haciendo clic en la portada o con → o Intro. La primera página muestra las cartas reunidas, el progreso, las horas de juego (de Steam, actualizadas al sincronizar), la carta más rara y la primera carta, firmada con tu nombre de Steam («Colección de …»). Las cartas van sujetas con esquineros en orden de desbloqueo; los marcos vacíos con «?» son los logros que te faltan. Pasa las páginas haciendo clic en la página o en su esquina, o con las flechas; Esc cierra el álbum. Los juegos completados al 100 % llevan un sello dorado en la portada.", "Haz clic en una carta (en la vitrina o en un álbum): se levanta, gira en el aire y aterriza delante de ti, con un sonido que sigue el volumen elegido en Ajustes. Haz clic en la carta (o pulsa Intro) para darle la vuelta: en el reverso verás cuántos jugadores de cada 1000 lo tienen, la fecha y hora, su puesto en tu colección, tu progreso en el juego y qué amigos que usan Fanfara lo tienen, y quién llegó primero. Esc o un clic fuera la cierra.", "Debajo de la carta abierta hay dos botones: «Copiar imagen» copia la carta (anverso o reverso) con su marco, para pegarla con Ctrl+V en Discord, WhatsApp o donde quieras; «Publicar en la vitrina» la publica en #bacheca-trofei del servidor de Discord de Fanfara, con tu nombre de Steam. Fanfara comprueba en Steam que el logro sea realmente tuyo; cada carta se publica una sola vez. Desde la vitrina también está «Ver en su álbum», que abre el álbum del juego en la página de la carta.", "Los álbumes se dividen en páginas: dos filas de libros por página. Pasa de página con las flechas ‹ › junto al orden, con las de abajo o con las teclas ← →; los puntos de abajo te dicen dónde estás. Con «Medianos», «Grandes» y «Muy grandes» (arriba o en Ajustes → Álbumes) eliges cuántos libros por fila: 6, 5 o 4."] },
    { k:"albumstyles", h:"Estilos de álbum", p:["Los álbumes de la Colección pueden cambiar de aspecto: «Clásico» (el de siempre), «Hierro y cuero», «Grimorio real», «Archivo holográfico», «Laca y oro» y «Latón y engranajes». Cada estilo tiene su portada, sus páginas, su marco y su fondo animado (velas, polvo, chispas, pétalos de cerezo, vapor…). Los juegos completados al 100 % llevan una cinta «100 %» en la esquina de la portada.", "Lo eliges en Ajustes → «Estilo de los álbumes». Ahí también está «Efectos de los álbumes»: Completos, Ligeros (menos animaciones) o Desactivados, útil en PC menos potentes."] },
    { k:"superfan", h:"Super Fanfara al 100 %", p:["Cuando desbloqueas el último logro de un juego suena la Super Fanfara: justo después de la notificación normal llega un gran «100 %» dorado con la imagen del juego, tus horas de juego, qué número de 100 % es para ti, confeti y música orquestal.", "Se activa y desactiva en Ajustes → «Super Fanfara al 100 %». El juego también cuenta al momento como 100 % en la clasificación."] },
    { k:"classifica", h:"Clasificación", p:["Una carrera por completar más juegos al 100 % (todos los logros desbloqueados). «Tus juegos» muestra tus juegos completados como cartas; «Mundial» es la clasificación pública de todos los usuarios de Fanfara, a la que entras solo si quieres; «Amigos» te compara con tus amigos de Steam que usan Fanfara. La puntuación se calcula en tu PC, sin inicio de sesión."] },
    { k:"friendcoll", h:"Colecciones de amigos", p:["En «Clasificación → Amigos», cada amigo que usa Fanfara tiene un botón «Colección»: púlsalo para ver su colección (vitrina, álbumes y cartas) y compararla con la tuya. Arriba ves cuántas cartas tenéis en común, cuántas te faltan y cuántas son solo tuyas; cada carta indica «La tienes» o «Te falta», cada álbum muestra también tu progreso y puedes mostrar solo los juegos que tenéis los dos.", "Después de cada sincronización, Fanfara envía una copia ligera de tu colección a su servicio en línea, y solo tus amigos de Steam pueden verla. Compartir está activado de forma predeterminada: desactívalo en Ajustes («Compartir mi colección con amigos») y la copia en línea se borra. Para ver las colecciones de tus amigos, tu lista de amigos de Steam debe ser pública."] },
    { k:"friend100", h:"Amigos al 100 %", p:["Si un amigo de Steam usa Fanfara y completa un juego al 100 %, te llega una notificación abajo a la derecha —también mientras juegas— con el juego, sus juegos al 100 % frente a los tuyos y dos campanadas suaves. También la encuentras en la campana del Inicio.", "En Ajustes puedes desactivar estas notificaciones («Avisarme cuando un amigo llegue al 100 %») o solo su sonido. Funciona con amigos que tienen Fanfara 0.6.0 o posterior y participan en la clasificación."] },
    { k:"sync", h:"Sincronización automática", p:["En el primer inicio, Fanfara importa sola todos tus logros, con iconos, fechas y rareza reales, sin iniciar sesión. Después captura los logros en directo mientras juegas.", "Cuando cierras un juego, lo actualiza al momento (iconos, rareza, estado 100 %); cada 12 horas hace una comprobación completa, aunque siga abierta. Puedes forzarla desde la etiqueta «Sincronizado» del inicio. Tu perfil de Steam necesita «Mi perfil» y «Detalles de los juegos» en Público: con «Solo amigos» o «Privado», Steam oculta tus logros y Fanfara no puede importarlos. En ese caso el inicio muestra un aviso rojo con «Cómo arreglarlo», las notificaciones siguen funcionando y Fanfara lo vuelve a comprobar sola cada 30 minutos.", "Steam manda: si reinicias logros en Steam (por ejemplo con un programa específico), la siguiente sincronización completa los quita también del Historial, la Colección y la clasificación. Steam puede tardar hasta una hora en mostrar el cambio."] },
    { k:"language", h:"Idioma", p:["Fanfara habla 5 idiomas. «Auto» sigue a Windows, o elige uno. Está todo traducido, incluidos los nombres de los rangos de cada estilo."] },
    { k:"theme", h:"Tema claro y oscuro", p:["El botón de arriba a la derecha cambia toda la app entre tema claro y oscuro."] },
    { k:"startup", h:"Iniciar con Windows y actualizaciones", p:["«Iniciar al encender el PC» arranca Fanfara solo, listo en la bandeja. «Buscar actualizaciones al iniciar» te avisa de nuevas versiones, instalables con un clic: Fanfara comprueba al iniciar, cada hora mientras sigue abierta y cuando vuelves a abrir su ventana. Al lado, «Buscar ahora» comprueba al momento: si hay una versión nueva, aparece «Actualizar ahora».", "Cuando sale una versión nueva, en el Inicio aparece un aviso abajo a la derecha: pulsa «Actualizar ahora» y Fanfara descarga la actualización, comprueba que es auténtica, se cierra, se instala sola y se vuelve a abrir en unos segundos mostrándote las novedades. Si estás jugando, espera a que cierres el juego. «Más tarde» oculta el aviso, pero lo encuentras en la campana."] },
    { k:"games", h:"Notificaciones en los juegos", p:["La opción «Mostrar notificaciones sobre juegos en pantalla completa» (recomendada, ya activada) prepara tus juegos de Steam. No tienes que hacer nada."] },
    { k:"exclusive", h:"Pantalla completa exclusiva", p:["Si un juego está en «Pantalla completa exclusiva», oyes la notificación pero no la ves: en ese modo Windows no deja dibujar nada encima del juego.", "Solución: en las opciones de vídeo del juego elige «Pantalla completa» sin exclusiva (a veces se llama «Sin bordes» o «Ventana sin bordes»). El juego sigue usando la frecuencia configurada en Windows, por ejemplo 165 Hz. Si Fanfara detecta que un juego estaba en exclusiva, te lo recuerda al cerrarlo."] },
    { k:"screens", h:"Varias pantallas", p:["Con dos o más pantallas, la notificación aparece por defecto en la pantalla donde juegas (la de la ventana activa). Si prefieres verla siempre en una pantalla concreta, elígela en la Configuración guiada, en el paso «Prueba».", "Si oyes el sonido pero no ves la notificación, abre la Configuración guiada, prueba la notificación y elige la pantalla correcta; si solo pasa dentro de un juego, revisa su modo de pantalla (ver «Pantalla completa exclusiva»)."] },
    { k:"framegen", h:"Frame Generation (avanzado)", p:["Algunos juegos con Frame Generation (DLSS 3, FSR 3) ocultan los overlays externos incluso en «Pantalla completa». Actívala para ver las notificaciones también ahí: requiere administrador y un reinicio, una sola vez. Es reversible y sin riesgo anticheat."] },
    { k:"steamtip", h:"Consejo: desactiva la notificación de Steam", p:["Para evitar duplicados, desactiva la de Steam: Steam → Configuración → Durante el juego → desactiva la notificación de desbloqueo de logros."] },
    { k:"testsave", h:"Ajustes en pestañas, guardados solos", p:["Los Ajustes se dividen en cuatro pestañas: Notificación (estilo, posición, duración, volumen y el botón Probar), Álbumes (estilo y efectos de los álbumes, tamaño de los libros en la Colección), Amigos y 100 % (compartir la colección, Super Fanfara, avisos de amigos y su sonido) y App (idioma, configuración guiada, inicio con Windows, actualizaciones, notificaciones en los juegos y Frame Generation).", "Ya no hay botón Guardar: cada cambio se guarda solo y aparece un pequeño «Guardado ✓». El botón Probar muestra una vista previa de la notificación con lo que has elegido."] },
    { k:"feedback", h:"Comentarios", p:["¿Has encontrado un problema o tienes una idea? Pulsa «Opinión» en la barra de arriba (también en el menú del icono junto al reloj): escribe un par de líneas y el mensaje llega directamente al desarrollador de Fanfara.", "Con tu texto solo se envían la versión de Fanfara, el idioma y la versión de Windows. Para problemas puedes adjuntar el registro técnico, limpio de datos personales."], a:"Enviar comentarios", href:"feedback.html" },
    { k:"opensource", h:"Proyecto de código abierto", p:["Fanfara es gratis y de código abierto. Código y novedades en GitHub: github.com/AmbroJack27/FanfaraOverlay. Proyecto amateur, no afiliado ni aprobado por las empresas de videojuegos."] }
  ]
};
